5 var(--font-display,serif);color:#103428;letter-spacing:-.4px;margin:0 0 12px}.ag-publication-section h3{font-size:16px;line-height:1.4;color:#173f32;margin:16px 0 8px}.ag-publication-section p,.ag-publication-section li{font-size:14px;line-height:1.78;color:#3b5448;overflow-wrap:anywhere}.ag-publication-section p{margin:8px 0 12px}.ag-publication-section>:last-child{margin-bottom:0!important}.ag-publication-section a{color:#215945;text-decoration:underline;text-underline-offset:3px}.ag-publication-section ul{padding-left:21px;margin:10px 0 14px}.ag-publication-section li{margin-bottom:7px}.ag-publication-subsection{padding:16px 20px;margin:12px 0;background:#f7faf5;border:1px solid #dbe6d8;border-left:4px solid #124b3b;border-radius:8px}.ag-publication-subsection h3{margin:0 0 6px!important;font-size:15.5px!important;color:#103428!important}.ag-publication-subsection p{margin:6px 0 0!important;font-size:13.5px!important;line-height:1.7!important}.ag-publication-subsection ul{margin:8px 0 0!important}.ag-publication-table{max-width:100%;overflow:auto;margin:14px 0;border:1px solid #d5e0cd;border-radius:8px}.ag-publication-table table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.65;min-width:0;table-layout:auto}.ag-publication-table th,.ag-publication-table td{text-align:left;padding:13px 16px;border-right:1px solid #dce4d5;border-bottom:1px solid #dce4d5;vertical-align:top;min-width:0;white-space:normal;word-break:normal;overflow-wrap:break-word;color:#385145}.ag-publication-table thead th{background:#eaf0df;color:#10382b;font-weight:700}.ag-publication-table tbody th{font-weight:650;background:#fafbf6;color:#123d2e;width:26%;min-width:160px}.ag-publication-table tr:last-child>*{border-bottom:0}.ag-publication-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:18px 0}.ag-publication-gallery:has(>figure:only-child){grid-template-columns:1fr!important;max-width:680px}.ag-publication-gallery:has(>figure:only-child) img{height:300px}.ag-publication-gallery figure{margin:0;min-width:0;border:1px solid #d8e4d4;border-radius:8px;overflow:hidden;background:#fafcf8;padding:10px}.ag-publication-gallery img{display:block;width:100%;height:220px;object-fit:cover;border-radius:6px}.ag-publication-gallery figcaption{font-size:12px;line-height:1.6;color:#4f6657;margin-top:8px;overflow-wrap:anywhere}.ag-publication-section .ag-publication-refs{font-size:10px;line-height:1.7;color:#819078;margin:10px 0 0}.ag-publication-refs a{margin-left:7px}.ag-publication-sources{padding-left:22px}.ag-publication-sources li{font-size:11px;scroll-margin-top:160px}.ag-publication-sources li>a{display:inline-flex;gap:6px;align-items:center}.ag-publication-sources li p{font-size:11px;line-height:1.7}.ag-publication-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.ag-publication-cards:has(>.ag-publication-card:only-child){grid-template-columns:1fr!important}.ag-publication-card{padding:20px;border:1px solid #d7e1cf;border-radius:8px;background:#fafcf7;text-decoration:none!important;min-width:0;transition:background .15s,border-color .15s}.ag-publication-card:hover{background:#f0f5e7;border-color:#9eb584}.ag-publication-card h3{font:650 16px/1.4 var(--font-display,serif);margin:10px 0 6px}.ag-publication-card p{font-size:13px;line-height:1.65;margin-bottom:12px}.ag-publication-card-kind{font-size:10px;text-transform:uppercase;letter-spacing:1.3px;color:#557465;font-weight:700}.ag-publication-card-logo{height:64px;display:flex;align-items:center;justify-content:flex-start;background:white;border-radius:4px;padding:8px;width:140px;max-width:100%}.ag-publication-card-logo img{width:100%;height:100%;object-fit:contain}.ag-publication-card-logo.is-dark{background:#173e30}.ag-publication-index{padding-block:45px 70px}.ag-publication-index-intro{max-width:780px;margin-bottom:26px}.ag-publication-index-intro h1{font:500 clamp(31px,4vw,48px)/1.15 var(--font-display,serif);color:#193e30;margin:14px 0}.ag-publication-index-intro p{font-size:14px;line-height:1.85;color:#5c705e}.ag-publication-index .ag-publication-cards{grid-template-columns:repeat(3,minmax(0,1fr))}.ag-publication-categories{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.ag-publication-categories a{font-size:12px;color:#315c3e;padding:9px 15px;border:1px solid #d5e0ca;border-radius:3px}.ag-publication-categories a[aria-current]{background:#1f4a36;color:#fff}.ag-publication-filter{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:22px 0}.ag-publication-filter input{font:inherit;min-height:44px;border:1px solid #cad9bd;border-radius:4px;padding:10px 14px;min-width:220px;background:white}.ag-publication-filter button{min-height:44px;padding:10px 18px;background:#244d34;color:white;border:0;border-radius:3px}.ag-publication-state-links{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 30px}.ag-publication-state-links a{color:#315e3e;text-decoration:underline;font-size:12px;line-height:1.7}@media(max-width:1050px){.ag-publication-layout{grid-template-columns:minmax(0,1fr) 260px;gap:26px}.ag-publication-cards{grid-template-columns:1fr}.ag-publication-toc ol{columns:1}.ag-publication-index .ag-publication-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.ag-publication-layout{grid-template-columns:1fr;padding-top:22px;gap:24px}.ag-publication-sidebar{position:static;max-width:none}.ag-publication-section{padding-block:20px!important;scroll-margin-top:135px}.ag-publication-index .ag-publication-cards{grid-template-columns:1fr}.ag-publication-toc{padding:18px}.ag-publication-gallery img{height:180px}.ag-publication-table table{min-width:560px}.ag-publication-table th,.ag-publication-table td{padding:12px;min-width:130px}.ag-publication-card{padding:18px}.ag-publication-hero .ag-detail-university-identity>span{width:85px;min-width:85px;height:75px}.ag-publication-hero .ag-detail-university-identity h1{font-size:30px}.ag-publication-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.ag-publication-cards,.ag-publication-gallery{grid-template-columns:1fr}.ag-publication-gallery img{height:220px}.ag-publication-section p,.ag-publication-section li{font-size:13px}.ag-publication-hero .ag-detail-university-identity{align-items:flex-start}.ag-publication-hero .ag-detail-university-identity h1{font-size:26px}.ag-publication-hero .ag-detail-university-identity>span{width:67px;min-width:67px;height:66px}.ag-publication-toc li{font-size:12px}.ag-publication-filter input{font-size:16px;width:100%;min-width:0}.ag-publication-filter button{width:100%}}
.ag-publication-image-caption{font-size:12px;line-height:1.6;margin:16px 0 0;color:#4b6259}.ag-publication-image-caption a{text-decoration:underline}

/* The approved agriculture palette, with distinct programme and campus layouts. */
.ag-detail .ag-text-link { color: var(--ag-green); }
.ag-detail-hero .ag-eyebrow { margin-bottom: 12px !important; font-size: 9px; }
.ag-detail-section-heading .ag-eyebrow { font-size: 9px; }
.ag-detail-topic-grid + .ag-text-link { margin-top: 15px; }
.ag-detail-fee-card > p:not(.ag-eyebrow) { color: #d0e0d4; font-size: 12px; line-height: 1.6; }
.ag-detail-faqs { border: 1px solid var(--ag-line); border-radius: 6px; overflow: hidden; }
.ag-detail-faqs details + details { border-top: 1px solid var(--ag-line); }
.ag-detail-faqs details[open] { background: #f1f6ec; }
.ag-detail-faqs summary { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; min-height: 47px; padding: 13px 16px; font-size: 12px; font-weight: 650; cursor: pointer; list-style: none; }
.ag-detail-faqs summary::-webkit-details-marker { display: none; }
.ag-detail-faqs summary svg { margin-top: 1px; flex-shrink: 0; }
.ag-detail-faqs details[open] summary svg { transform: rotate(180deg); }
.ag-detail-faqs details p { margin: -3px 16px 15px; font-size: 12px; }
.ag-detail-closing p:not(.ag-eyebrow) { margin-top: 12px; color: #caddcc; font-size: 13px; }
.ag-detail-dialog__intro .ag-eyebrow { padding-right: 30px; font-size: 9px; }

/* A campus profile and full-width course directory distinguish the university page. */
@media (max-width: 700px) {
  .ag-detail-hero__actions > .ag-text-link { min-height: 35px; }
  .ag-detail-section-heading .ag-eyebrow { font-size: 8px; }
  .ag-detail-faqs summary { font-size: 12px; padding: 13px; }
  .ag-detail-faqs details p { margin-inline: 13px; }
}

/* Programme pages: researched content sections (programme-content-sections.tsx) */
.ag-eyebrow { display: flex; align-items: center; gap: 10px; margin: 0 0 7px !important; color: var(--ag-green); font-size: 10px; font-weight: 760; line-height: 1.5; letter-spacing: 1.7px; text-transform: uppercase; }
.ag-eyebrow::before { content: ''; display: inline-block; width: 21px; height: 5px; background: var(--ag-green); flex-shrink: 0; }
.ag-eyebrow--light { color: #e3eee6; }
.ag-eyebrow--light::before { background: #d8e8c6; }
.ag-text-link { display: inline-flex; align-items: center; justify-content: flex-start; gap: 10px; padding: 0; border: 0; background: transparent; color: var(--ag-green); font-size: 13px; font-weight: 650; line-height: 1.5; text-align: left; text-decoration: underline; text-underline-offset: 3px; }
.ag-text-link:hover { color: #398066; }
.ag-text-link.ag-button { padding: 9px 20px; border: 1px solid var(--ag-green); background: var(--ag-green); text-decoration: none; }
.ag-text-link.ag-button:hover { background: #1e614d; }
.ag-text-link svg { flex-shrink: 0; }

/* The home uses its approved chrome; legacy catalogue pages retain their shell. */

/* 01 — Agrico Hero Section (Enhanced Responsive Split-Layout Slider) */

/* Finder Search Form */

/* Quick Filter Links */

/* Visual Column / Slider Card */

/* Glassmorphic Overlay Bar on Slider */

/* Slider Controls */

/* Progress Indicators */

/* Responsive Media Queries */

/* Preserved Classic Hero styles */

/* 02 — a shared guidance ribbon */
.ag-help-strip .ag-eyebrow { display: block; padding-right: 15px; margin-bottom: 0 !important; font-size: 12px; color: #173b2e; line-height: 1.7; letter-spacing: 1.8px; }
.ag-help-strip .ag-eyebrow::before { display: block; margin-bottom: 8px; }

/* 03 — the locked curriculum explorer */

/* 04 — institutions and campus-selection guidance */

/* 05 — academic technology, with a real teaching workshop */
.ag-technology .ag-eyebrow { margin-bottom: 10px !important; }

/* 06 — the approved Agriculture versus Agricultural Engineering comparison */

/* 07 — a clear preparation journey */

/* 08 — degree-to-learning-to-career pathways */
.ag-pathway-action .ag-text-link {
  font-size: 12px;
  text-decoration: none;
  gap: 5px;
  white-space: nowrap;
}

/* 09 — a student guide shelf */
.ag-guide-card .ag-text-link { position: absolute; left: 20px; bottom: 17px; z-index: 1; font-size: 12px; }

/* 10 — education updates, without fabricated current announcements */
/* News & updates slider */
.ag-updates-controls .ag-text-link { margin-right: 6px; }
.ag-updates-track .ag-update-copy .ag-text-link { margin-top: auto; }
.ag-update-copy .ag-text-link { font-size: 12px; }

/* 11 — readable, keyboard-operable questions */

/* 12 — the real existing server-action enquiry flow */

/* The restrained approved footer. */

/* Native dialogs preserve focus trapping, Escape and accessible reading order. */
.ag-dialog-eyebrow-row .ag-eyebrow {
  margin: 0;
}
.ag-dialog__content > .ag-text-link { margin-top: 17px; }

/* Modal Enquiry Form */

/* Modal Success State */

/* Hero & FAQ counselling buttons */

/* Keep the reference's proportions on desktop; reflow by content on smaller screens. */
@media (max-width: 1150px) {
  .ag-help-strip .ag-eyebrow { font-size: 10px; }
  .ag-pathway-action .ag-text-link { font-size: 10px; }
  .ag-guide-card .ag-text-link { left: 15px; }
}
@media (max-width: 1000px) {
  .ag-hero__copy .ag-eyebrow { font-size: 9px; }
  .ag-help-strip .ag-eyebrow { display: none; }
}
@media (max-width: 900px) {
  .ag-pathway-action .ag-text-link { max-width: none; font-size: 12px; }
}
@media (max-width: 700px) {
  .ag-eyebrow { font-size: 9px; letter-spacing: 1.45px; }
  .ag-guide-card .ag-text-link { left: 19px; bottom: 15px; }
  .ag-home button.ag-text-link { min-height: 30px; }
}
@media (max-width: 450px) {
  .ag-hero__copy .ag-eyebrow { font-size: 8px; letter-spacing: 1.2px; }
}

