/* Keep the reference's proportions on desktop; reflow by content on smaller screens. */
@media (max-width: 1150px) {
  .ag-help-strip .ag-eyebrow { font-size: 10px; }
  .ag-pathway-action .ag-text-link { font-size: 10px; }
  .ag-guide-card .ag-text-link { left: 15px; }
}
@media (max-width: 1000px) {
  .ag-hero__copy .ag-eyebrow { font-size: 9px; }
  .ag-help-strip .ag-eyebrow { display: none; }
}
@media (max-width: 900px) {
  .ag-pathway-action .ag-text-link { max-width: none; font-size: 12px; }
}
@media (max-width: 700px) {
  .ag-eyebrow { font-size: 9px; letter-spacing: 1.45px; }
  .ag-guide-card .ag-text-link { left: 19px; bottom: 15px; }
  .ag-home button.ag-text-link { min-height: 30px; }
}
@media (max-width: 450px) {
  .ag-hero__copy .ag-eyebrow { font-size: 8px; letter-spacing: 1.2px; }
}

