  .ag-hero__copy .ag-eyebrow { font-size: 9px; }
  .ag-help-strip .ag-eyebrow { display: none; }
}
@media (max-width: 900px) {
  .ag-pathway-action .ag-text-link { max-width: none; font-size: 12px; }
}
