/* The approved agriculture palette, with distinct programme and campus layouts. */
.ag-detail .ag-text-link { color: var(--ag-green); }
.ag-detail-hero .ag-eyebrow { margin-bottom: 12px !important; font-size: 9px; }
.ag-detail-section-heading .ag-eyebrow { font-size: 9px; }
.ag-detail-topic-grid + .ag-text-link { margin-top: 15px; }
.ag-detail-fee-card > p:not(.ag-eyebrow) { color: #d0e0d4; font-size: 12px; line-height: 1.6; }
.ag-detail-faqs { border: 1px solid var(--ag-line); border-radius: 6px; overflow: hidden; }
.ag-detail-faqs details + details { border-top: 1px solid var(--ag-line); }
.ag-detail-faqs details[open] { background: #f1f6ec; }
.ag-detail-faqs summary { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; min-height: 47px; padding: 13px 16px; font-size: 12px; font-weight: 650; cursor: pointer; list-style: none; }
.ag-detail-faqs summary::-webkit-details-marker { display: none; }
.ag-detail-faqs summary svg { margin-top: 1px; flex-shrink: 0; }
.ag-detail-faqs details[open] summary svg { transform: rotate(180deg); }
.ag-detail-faqs details p { margin: -3px 16px 15px; font-size: 12px; }
.ag-detail-closing p:not(.ag-eyebrow) { margin-top: 12px; color: #caddcc; font-size: 13px; }
.ag-detail-dialog__intro .ag-eyebrow { padding-right: 30px; font-size: 9px; }

/* A campus profile and full-width course directory distinguish the university page. */
@media (max-width: 700px) {
  .ag-detail-hero__actions > .ag-text-link { min-height: 35px; }
  .ag-detail-section-heading .ag-eyebrow { font-size: 8px; }
  .ag-detail-faqs summary { font-size: 12px; padding: 13px; }
  .ag-detail-faqs details p { margin-inline: 13px; }
}

/* Programme pages: researched content sections (programme-content-sections.tsx) */
.ag-eyebrow { display: flex; align-items: center; gap: 10px; margin: 0 0 7px !important; color: var(--ag-green); font-size: 10px; font-weight: 760; line-height: 1.5; letter-spacing: 1.7px; text-transform: uppercase; }
.ag-eyebrow::before { content: ''; display: inline-block; width: 21px; height: 5px; background: var(--ag-green); flex-shrink: 0; }
.ag-eyebrow--light { color: #e3eee6; }
.ag-eyebrow--light::before { background: #d8e8c6; }
.ag-text-link { display: inline-flex; align-items: center; justify-content: flex-start; gap: 10px; padding: 0; border: 0; background: transparent; color: var(--ag-green); font-size: 13px; font-weight: 650; line-height: 1.5; text-align: left; text-decoration: underline; text-underline-offset: 3px; }
.ag-text-link:hover { color: #398066; }
.ag-text-link.ag-button { padding: 9px 20px; border: 1px solid var(--ag-green); background: var(--ag-green); text-decoration: none; }
.ag-text-link.ag-button:hover { background: #1e614d; }
.ag-text-link svg { flex-shrink: 0; }

